            mid = (lo + hi) // 2
            merge_sort(lo, mid)
            merge_sort(mid, hi)
            if nums[mid - 1] <= nums[mid]:
                return
            i, j, k = lo, mid, lo
            while i < mid and j < hi:
                if nums[i] <= nums[j]:
