            while i < mid:
                buf[k] = nums[i]
                i += 1
                k += 1
            while j < hi:
                buf[k] = nums[j]
                j += 1
                k += 1
            nums[lo:hi] = buf[lo:hi]

        merge_sort(0, n)
        return nums

